import { parse as babelParse } from "@babel/parser";

/**
 * Parse JavaScript or Node.js source into Babel's File AST.
 *
 * `unambiguous` accepts ES modules when imports or exports are present and
 * otherwise treats the file as a script, which is useful for Node.js code.
 *
 * @param {string} source Source code to parse.
 * @returns {import("@babel/parser").ParseResult<import("@babel/types").File>}
 */
export function parse(source) {
  return babelParse(source, {
    sourceType: "unambiguous",
  });
}
